def d4(a):
 a=np.asarray(a); return [np.rot90(a,k) for k in range(4)]+[np.rot90(np.fliplr(a),k) for k in range(4)]
for ia,aa in enumerate(d4(A7)):
 for ib,bb in enumerate(d4(B7)):
  if aa.shape==O.shape and bb.shape==O.shape and np.array_equal(aa&bb,O): print('exact',ia,ib)

import re
texts=[item.get('text','') for u in users for item in u['content'] if item.get('type')=='text']
def parse_demo(text,n):
 pat=rf'Demo pair {n} input \((\d+)x(\d+)\):\n(.*?)\nDemo pair {n} output \((\d+)x(\d+)\):\n(.*?)(?=\n\nSame instance|$)'
 m=re.search(pat,text,re.S)
 if not m: return None
 ih,iw=map(int,m.group(1,2)); oh,ow=map(int,m.group(4,5))
 inp=[[int(x) for x in line.split()] for line in m.group(3).splitlines() if line.strip()]
 out=[[int(x) for x in line.split()] for line in m.group(5).strip().splitlines() if line.strip()]
 return inp,out,(ih,iw,oh,ow)
demos={}
for n in range(1,6):
 for t in texts:
  if f'Demo pair {n} input' in t:
   demos[n]=parse_demo(t,n); break
print({n:(d[2],len(d[0]),len(d[1])) for n,d in demos.items()})

